add_filter( 'woocommerce_shipping_package_name', 'perfectpixel_rename_shipping_totals_label', 10, 3 );

function perfectpixel_rename_shipping_totals_label( $name, $index, $package ) {
	// Keep WooCommerce's numbering when the cart is split in several packages.
	return $index > 0 ? '{{shipping_totals_label}} ' . ( $index + 1 ) : '{{shipping_totals_label}}';
}
